use super::*;

fn color(c: char) -> Option<Color> {
    match c {
        'B' => Some(Color::Black),
        'W' => Some(Color::White),
        _ => None,
    }
}

fn output_string(stones: &[Option<Color>]) -> String {
    stones
        .iter()
        .map(|s| match s {
            Some(Color::Black) => 'B',
            Some(Color::White) => 'W',
            None => '.',
        })
        .collect()
}

#[test]
fn java_oracle_positions_match_every_stone_komi_turn_warning_and_added_order() {
    // Generated by generate.py, compiling the unchanged reference Tsumego.java;
    // its temporary adapters only capture board I/O, flattening and warnings.
    let fixture = include_str!("../../../../fixtures/tsumego/java-golden.txt");
    let mut count = 0;
    for line in fixture.lines().filter(|line| !line.starts_with('#')) {
        let fields: Vec<_> = line.split('|').collect();
        let size = BoardSize::new(fields[1].parse().unwrap(), fields[2].parse().unwrap()).unwrap();
        let input: Vec<_> = fields[8].chars().map(color).collect();
        let options = TsumegoOptions {
            wall_distance: fields[3].parse().unwrap(),
            attacker: match fields[4] {
                "Black" => TsumegoAttacker::Black,
                "White" => TsumegoAttacker::White,
                _ => TsumegoAttacker::Auto,
            },
            ko_threat: match fields[5] {
                "Attacker" => TsumegoKoThreat::Attacker,
                "Defender" => TsumegoKoThreat::Defender,
                "None" => TsumegoKoThreat::None,
                _ => TsumegoKoThreat::Both,
            },
            to_play: match fields[6] {
                "Black" => TsumegoToPlay::Black,
                "White" => TsumegoToPlay::White,
                _ => TsumegoToPlay::Inherit,
            },
        };
        let result = generate(
            size,
            &input,
            color(fields[7].chars().next().unwrap()).unwrap(),
            options,
        )
        .unwrap();
        let context = &fields[..8];
        assert_eq!(
            output_string(&result.stones),
            fields[9],
            "board {context:?}"
        );
        let expected_komi = if fields[10] == "-" {
            None
        } else {
            Some(fields[10].parse().unwrap())
        };
        assert_eq!(result.komi, expected_komi, "komi {context:?}");
        assert_eq!(
            Some(result.attacker),
            color(fields[11].chars().next().unwrap()),
            "attacker {context:?}"
        );
        assert_eq!(
            Some(result.to_play),
            color(fields[12].chars().next().unwrap()),
            "turn {context:?}"
        );
        assert_eq!(
            output_string(
                &result
                    .ko_warnings
                    .iter()
                    .copied()
                    .map(Some)
                    .collect::<Vec<_>>()
            ),
            fields[13],
            "warnings {context:?}"
        );
        let added: String = result
            .added_stones
            .iter()
            .map(|(c, p)| {
                format!(
                    "{}{},{};",
                    if *c == Color::Black { 'B' } else { 'W' },
                    p.x,
                    p.y
                )
            })
            .collect();
        assert_eq!(added, fields[14], "added {context:?}");
        assert_eq!(output_string(&input), fields[8], "input never changes");
        count += 1;
    }
    assert_eq!(count, 1078);
}

#[test]
fn validation_rejects_bad_dimensions_length_and_zero_distance() {
    assert!(matches!(
        generate(
            BoardSize {
                width: 1,
                height: 19
            },
            &[],
            Color::Black,
            TsumegoOptions::default()
        ),
        Err(TsumegoError::BoardSize(_))
    ));
    assert!(matches!(
        generate(
            BoardSize::new(19, 19).unwrap(),
            &[],
            Color::Black,
            TsumegoOptions::default()
        ),
        Err(TsumegoError::BoardLength { .. })
    ));
    let stones = vec![None; 361];
    assert_eq!(
        generate(
            BoardSize::new(19, 19).unwrap(),
            &stones,
            Color::Black,
            TsumegoOptions {
                wall_distance: 0,
                ..TsumegoOptions::default()
            }
        ),
        Err(TsumegoError::WallDistance)
    );
}

#[test]
fn maximum_distance_is_safe_and_preserves_java_noop_even_when_forcing_turn() {
    let mut stones = vec![None; 361];
    stones[180] = Some(Color::White);
    let result = generate(
        BoardSize::new(19, 19).unwrap(),
        &stones,
        Color::White,
        TsumegoOptions {
            wall_distance: u32::MAX,
            to_play: TsumegoToPlay::Black,
            ..TsumegoOptions::default()
        },
    )
    .unwrap();
    assert_eq!(result.stones, stones);
    assert_eq!(result.to_play, Color::White);
    assert_eq!(result.komi, None);
    assert!(result.added_stones.is_empty());
    assert!(result.ko_warnings.is_empty());
}

fn center() -> Vec<Option<Color>> {
    let mut stones = vec![None; 361];
    for (x, y) in [
        (8, 8),
        (9, 8),
        (10, 8),
        (11, 8),
        (8, 9),
        (11, 9),
        (8, 10),
        (9, 10),
        (10, 10),
        (11, 10),
    ] {
        stones[y * 19 + x] = Some(Color::Black);
    }
    stones[9 * 19 + 9] = Some(Color::White);
    stones[9 * 19 + 10] = Some(Color::White);
    stones
}

fn build(stones: &[Option<Color>], options: TsumegoOptions) -> TsumegoOutput {
    generate(
        BoardSize::new(19, 19).unwrap(),
        stones,
        Color::White,
        options,
    )
    .unwrap()
}

#[test]
fn auto_attacker_uses_java_count_fallback_and_forced_colors_override() {
    let black = center();
    let white: Vec<_> = black.iter().map(|s| s.map(Color::opponent)).collect();
    assert_eq!(
        build(&black, TsumegoOptions::default()).attacker,
        Color::Black
    );
    assert_eq!(
        build(&white, TsumegoOptions::default()).attacker,
        Color::White
    );
    let mut tie = vec![None; 361];
    tie[180] = Some(Color::Black);
    tie[181] = Some(Color::White);
    assert_eq!(
        build(&tie, TsumegoOptions::default()).attacker,
        Color::Black
    );
    for (attacker, expected) in [
        (TsumegoAttacker::Black, Color::Black),
        (TsumegoAttacker::White, Color::White),
    ] {
        assert_eq!(
            build(
                &black,
                TsumegoOptions {
                    attacker,
                    ..TsumegoOptions::default()
                }
            )
            .attacker,
            expected
        );
    }
}

#[test]
fn all_turn_options_and_wall_distance_preserve_problem_stones() {
    let originals = center();
    for (to_play, expected) in [
        (TsumegoToPlay::Inherit, Color::White),
        (TsumegoToPlay::Black, Color::Black),
        (TsumegoToPlay::White, Color::White),
    ] {
        assert_eq!(
            build(
                &originals,
                TsumegoOptions {
                    to_play,
                    ..TsumegoOptions::default()
                }
            )
            .to_play,
            expected
        );
    }
    let close = build(
        &originals,
        TsumegoOptions {
            ko_threat: TsumegoKoThreat::None,
            ..TsumegoOptions::default()
        },
    );
    let far = build(
        &originals,
        TsumegoOptions {
            wall_distance: 3,
            ko_threat: TsumegoKoThreat::None,
            ..TsumegoOptions::default()
        },
    );
    assert_eq!(close.stones[9 * 19 + 6], Some(Color::Black));
    assert_eq!(far.stones[9 * 19 + 6], None);
    assert_eq!(far.stones[9 * 19 + 4], Some(Color::Black));
    for (index, color) in originals.iter().enumerate().filter(|(_, s)| s.is_some()) {
        assert_eq!(close.stones[index], *color);
        assert_eq!(far.stones[index], *color);
    }
}

#[test]
fn ko_options_map_to_ui_attacker_and_defender_and_report_missing_room() {
    let stones = center();
    let outputs: Vec<_> = [
        TsumegoKoThreat::None,
        TsumegoKoThreat::Attacker,
        TsumegoKoThreat::Defender,
        TsumegoKoThreat::Both,
    ]
    .into_iter()
    .map(|ko_threat| {
        build(
            &stones,
            TsumegoOptions {
                ko_threat,
                ..TsumegoOptions::default()
            },
        )
    })
    .collect();
    assert_eq!(outputs[0].stones[0], Some(Color::White));
    assert_eq!(outputs[1].stones[0], None);
    assert_eq!(outputs[2].stones[0], Some(Color::White));
    assert_eq!(outputs[3].stones[0], None);
    assert_eq!(outputs[0].stones[18 * 19 + 18], Some(Color::Black));
    assert_eq!(outputs[1].stones[18 * 19 + 18], Some(Color::Black));
    assert_eq!(outputs[2].stones[18 * 19 + 18], None);
    assert_eq!(outputs[3].stones[18 * 19 + 18], None);
    let mut tall = vec![None; 361];
    for y in 1..=17 {
        tall[y * 19] = Some(Color::Black);
        tall[y * 19 + 1] = Some(Color::White);
    }
    let none = build(
        &tall,
        TsumegoOptions {
            ko_threat: TsumegoKoThreat::None,
            ..TsumegoOptions::default()
        },
    );
    let defender = build(
        &tall,
        TsumegoOptions {
            ko_threat: TsumegoKoThreat::Defender,
            ..TsumegoOptions::default()
        },
    );
    assert_eq!(none.stones, defender.stones);
    assert_eq!(defender.ko_warnings, vec![Color::White]);
}
